import heapq

def match(orders):
    buy_heap = []  # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    info = {}  # id -> dict(side, price, qty, seq, active)
    seq_counter = 0
    trades = []

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            d = info.get(oid)
            if d is None or not d['active'] or d['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            d = info.get(oid)
            if d is None or not d['active'] or d['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            d = info.get(oid)
            if d is not None and d['active'] and d['qty'] > 0:
                d['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                top_price, top_seq, top_id = sell_heap[0]
                if typ != 'market' and price < top_price:
                    break
                resting = info[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, top_id, resting['price'], trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    resting['active'] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
                seq_counter += 1
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, top_seq, top_id = buy_heap[0]
                top_price = -negprice
                if typ != 'market' and price > top_price:
                    break
                resting = info[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([top_id, oid, resting['price'], trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    resting['active'] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                heapq.heappush(sell_heap, (price, seq_counter, oid))
                seq_counter += 1

    return trades

